dictionary:
---
import ResearchPaperTable from './ResearchPaperTable.astro';
import {
  ADVISOR_Q03_CUSTOM_PANEL,
  ADVISOR_Q04_CAPACITY,
  ADVISOR_Q05_FROZEN,
} from '../../data/openEvoAdvisorTenQuestions';
import q01Csv from '../../data/research-evidence/advisor-q01-three-way-curve.csv?raw';
import ExternalBrandMark from '../common/ExternalBrandMark';
import PaperIntervalPlot from './PaperIntervalPlot.astro';
import PublicationPlot from './PublicationPlot.astro';
import NativeSvgChartReader from './NativeSvgChartReader.astro';

type Variant = 'q01' | 'q02' | 'q03' | 'q04' | 'q05' | 'q07';
interface Props { variant: Variant }
const { variant } = Astro.props;
// This committed CSV has the exact same Git blob SHA as PR #628's sealed science output.
// Only existing, fixed held-out checkpoint scores are read. No evaluation runs here.
const q01CurveHref = 'https://github.com/mykcs/openevo-experiment/blob/48e1368c7afc260a1745a49e6c7c173bfbb172b2/docs/evidence/advisor-q01-horizon-plateau-20261001/three-way-curve.csv';
const q01ResultHref = 'https://github.com/mykcs/openevo-experiment/blob/48e1368c7afc260a1745a49e6c7c173bfbb172b2/docs/evidence/advisor-q01-horizon-plateau-20261001/Q01_THREE_WAY_RESULT.json';

const q01Data = q01Csv.trim().split('\n').slice(1).map((line) => {
  const columns = line.split(',');
  return { key: columns[0] ?? '', round: Number(columns[2]), actualUpdates: Number(columns[3]), score: Number(columns[4])*100, exact: Number(columns[5]) };
});
const q01Specs = [
  { key:'ordinary_openevo',name:'普通 OpenEVO',takeaway:'第 120 次更新约 60.40 分，第 160 次约 60.11 分；额外训练没有带来明显增分。' },
  { key:'bounded_state',name:'Bounded',takeaway:'第 120 轮约 58.72 分，到第 150 轮约 67.25 分；后段仍有收益。' },
  { key:'delta_beta_family',name:'历史 β/GDR',takeaway:'第 130 轮约 58.16 分，到第 160 轮约 45.24 分；后段下降约 12.93 分。' },
] as const;
const q01Series = q01Specs.map((spec)=>({ ...spec,values:q01Data.filter((item)=>item.key===spec.key) }));
const q01Rounds = q01Series[0]?.values.map((item)=>item.round) ?? [];
if(q01Data.length !== 33 || q01Series.some((series)=>series.values.length!==11 || series.values.some((point,index)=>point.round!==q01Rounds[index] || !Number.isFinite(point.score)))){
  throw new Error('Q01 frozen curve has unexpected source coverage');
}
const q01X = (round:number) => 63 + (round-1)/159*650;
const q01Y = (score:number) => 28 + (100-score)*2.22;
const q01PhoneX = (round:number) => 32 + (round-1)/159*294;
const q01PhoneY = (score:number) => 21 + (100-score)*1.68;
const earlySft = [
  { name: 'SFT · 1 遍', score: 35.53 },
  { name: 'SFT · 2 遍', score: 28.30 },
  { name: 'SFT · 3 遍', score: 24.10 },
];
// Q03: the source-bound HTML table and the precompiled PGFPlots file share
// the same frozen data; scripts/verify-q03-pgfplot.mjs checks data/source hashes.
---
{variant === 'q01' && (
  <figure class="advisor-viz advisor-viz--q01" data-report-figure="q01-horizon" data-evidence-shape="measured-score-curves" data-paper-figure="true">
    <header class="advisor-viz__heading">
      <strong>训练进度与 WebShop Task Score</strong>
      <span>冻结 64 题 · 每种方法 11 个实际保存点</span>
    </header>
    <p class="advisor-viz__q01-axis-explainer" data-q01-axis-scope><strong>横轴使用两种计数：</strong>普通 OpenEVO 按实际参数更新次数统计；Bounded 和历史 β/GDR 按已完成的 Stage2 轮数统计，其中一些轮次没有真正更新参数。<strong>横轴数字相同，不代表实际更新次数或计算成本相同。</strong></p>
    <PublicationPlot
      id="q01-three-way"
      src="/research/seed-openevo/figures/q01-three-way-pgfplots.svg"
      mobileSrc="/research/seed-openevo/figures/q01-three-way-mobile-pgfplots.svg"
      captionId="advisor-q01-paper-caption"
      widthTier="double"
      naturalWidth={462}
      naturalHeight={273}
      loading="eager"
      alt="同一冻结 64 道 WebShop 题上三条历史路线各 11 个实测保存点的 Task Score 曲线，纵轴 0 至 100。普通 OpenEVO 按参数更新次数，Bounded 与历史 β/GDR 按 Stage2 完成轮数；横轴刻度相同不代表同等实际更新次数。普通方法后段变化较小，Bounded 至 150 轮继续提升，历史 β/GDR 后段下降。"
    />
    <figcaption id="advisor-q01-paper-caption"><strong>图 1｜</strong>三种参数更新方法在同一冻结 64 题上的 Task Score（满分 100）。每条曲线包含 11 个真实保存点，线段只连接已测点。普通 OpenEVO 横轴为实际参数更新次数；Bounded 和历史 β/GDR 横轴为已完成的 Stage2 轮数，后两组包含未实际更新参数的轮次。同一横轴刻度不是相同的训练计算量，不应据此进行等成本排名。</figcaption>
    <details class="advisor-viz__q01-raw-svg" data-q01-raw-svg>
      <summary>展开查看原始 33 个保存点的 SVG（技术核查）</summary>
    <div class="advisor-viz__q01-legend" role="group" aria-label="三种方法的线型和点形图例">
      {q01Series.map((item) => (
        <span class={'advisor-viz__q01-legend-item advisor-viz__q01-series--'+item.key}>
          <svg viewBox="0 0 34 14" focusable="false" aria-hidden="true">
            <line class="advisor-viz__q01-curve" x1="2" x2="32" y1="7" y2="7" />
            {item.key === 'ordinary_openevo'
              ? <circle class="advisor-viz__q01-point" cx="17" cy="7" r="3" />
              : item.key === 'bounded_state'
                ? <rect class="advisor-viz__q01-point" x="14" y="4" width="6" height="6" />
                : <polygon class="advisor-viz__q01-point" points="17,3 20.6,10 13.4,10" />}
          </svg>
          <span>{item.name}</span>
        </span>
      ))}
    </div>
    <div class="q01-native-reader">
    <NativeSvgChartReader id="q01-native-curve" label="三种方法的原始技术核查曲线" nativeWidth={888}>
    <svg class="advisor-viz__q01-chart advisor-viz__q01-chart--desktop" viewBox="0 0 740 310" role="img" aria-label="三种方法的真实开发集任务成绩随训练进度变化" aria-describedby="advisor-q01-chart-desc">
      <desc id="advisor-q01-chart-desc">每条曲线来自十一个真实保存的模型版本，在同一批事先固定的六十四道购物题上测试。普通 OpenEVO 第一百二十次更新后的成绩几乎没有提高；Bounded 一百五十轮之前还在提高；历史 beta GDR 一百三十轮之后下降。纵轴是零到一百的 Task Score。</desc>
      {[0,25,50,75,100].map((tick) => (
        <g>
          {tick > 0 && tick < 100 && <line class="advisor-viz__q01-grid" x1="63" x2="713" y1={q01Y(tick)} y2={q01Y(tick)} />}
          <text class="advisor-viz__q01-axis" x="52" y={q01Y(tick)+4} text-anchor="end">{tick}</text>
        </g>
      ))}
      <path class="advisor-viz__q01-axes" d="M63 28 V250 H713" />
      {[1,40,80,120,160].map((tick) => (
        <g>
          <line class="advisor-viz__q01-tick" x1={q01X(tick)} x2={q01X(tick)} y1="250" y2="254" />
          <text class="advisor-viz__q01-axis" x={q01X(tick)} y="273" text-anchor="middle">{tick}</text>
        </g>
      ))}
      {q01Series.map((item) => (
        <g class={'advisor-viz__q01-series advisor-viz__q01-series--'+item.key} data-q01-line={item.key}>
          <polyline class="advisor-viz__q01-curve" points={item.values.map((v) => q01X(v.round)+','+q01Y(v.score)).join(' ')} />
          {item.values.map((v) => (
            item.key === 'ordinary_openevo'
              ? <circle class="advisor-viz__q01-point" cx={q01X(v.round)} cy={q01Y(v.score)} r="3" />
              : item.key === 'bounded_state'
                ? <rect class="advisor-viz__q01-point" x={q01X(v.round)-2.8} y={q01Y(v.score)-2.8} width="5.6" height="5.6" />
                : <polygon class="advisor-viz__q01-point" points={[q01X(v.round)+','+(q01Y(v.score)-3.5),(q01X(v.round)+3.6)+','+(q01Y(v.score)+3),(q01X(v.round)-3.6)+','+(q01Y(v.score)+3)].join(' ')} />
          ))}
        </g>
      ))}
      <text class="advisor-viz__q01-axis advisor-viz__q01-axis-label" x="63" y="15">Task Score（满分 100 分）</text>
      <text class="advisor-viz__q01-axis advisor-viz__q01-axis-label" x="713" y="301" text-anchor="end">训练进度（口径见上）</text>
    </svg>
    <svg class="advisor-viz__q01-chart advisor-viz__q01-chart--phone" viewBox="0 0 340 232" role="img" aria-label="三条方法的真实训练成绩变化，手机视图" aria-describedby="advisor-q01-phone-desc">
      <desc id="advisor-q01-phone-desc">每种方法十一个已测模型版本的做题成绩。普通 OpenEVO 一百二十次更新之后进步很少，Bounded 到一百五十轮仍有提升，历史 beta GDR 一百三十轮后开始下降。</desc>
      {[0,25,50,75,100].map((tick) => (
        <g>
          {tick > 0 && tick < 100 && <line class="advisor-viz__q01-grid" x1="32" x2="326" y1={q01PhoneY(tick)} y2={q01PhoneY(tick)} />}
          <text class="advisor-viz__q01-axis" x="26" y={q01PhoneY(tick)+4} text-anchor="end">{tick}</text>
        </g>
      ))}
      <path class="advisor-viz__q01-axes" d="M32 21 V189 H326" />
      {[1,80,120,160].map((tick) => (
        <g>
          <line class="advisor-viz__q01-tick" x1={q01PhoneX(tick)} x2={q01PhoneX(tick)} y1="189" y2="193" />
          <text class="advisor-viz__q01-axis" x={q01PhoneX(tick)} y="208" text-anchor="middle">{tick}</text>
        </g>
      ))}
      {q01Series.map((item) => (
        <g class={'advisor-viz__q01-series advisor-viz__q01-series--'+item.key} data-q01-phone-line={item.key}>
          <polyline class="advisor-viz__q01-curve" points={item.values.map((v) => q01PhoneX(v.round)+','+q01PhoneY(v.score)).join(' ')} />
          {item.values.map((v) => (
            item.key === 'ordinary_openevo'
              ? <circle class="advisor-viz__q01-point" cx={q01PhoneX(v.round)} cy={q01PhoneY(v.score)} r="2.7" />
              : item.key === 'bounded_state'
                ? <rect class="advisor-viz__q01-point" x={q01PhoneX(v.round)-2.6} y={q01PhoneY(v.score)-2.6} width="5.2" height="5.2" />
                : <polygon class="advisor-viz__q01-point" points={[q01PhoneX(v.round)+','+(q01PhoneY(v.score)-3.1),(q01PhoneX(v.round)+3.2)+','+(q01PhoneY(v.score)+2.9),(q01PhoneX(v.round)-3.2)+','+(q01PhoneY(v.score)+2.9)].join(' ')} />
          ))}
        </g>
      ))}
      <text class="advisor-viz__q01-axis advisor-viz__q01-axis-label" x="33" y="12">Task Score（满分 100 分）</text>
      <text class="advisor-viz__q01-axis advisor-viz__q01-axis-label" x="326" y="227" text-anchor="end">训练进度（计数不同）</text>
    </svg>
    </NativeSvgChartReader></div>

    </details>
    <div class="advisor-viz__q01-reading">
      {q01Series.map((item) => <p><strong>{item.name}：</strong>{item.takeaway}</p>)}
    </div>
    <p class="advisor-viz__q01-source">数据与规则：<a href={q01CurveHref} target="_blank" rel="noopener noreferrer"><ExternalBrandMark href={q01CurveHref} />11 个保存点的原始 CSV</a> · <a href={q01ResultHref} target="_blank" rel="noopener noreferrer"><ExternalBrandMark href={q01ResultHref} />判断何时停止的规则与原始结果</a></p>
    <details class="advisor-viz__details">
      <summary>怎样判断继续训练是否还值得？各个版本是多少分？</summary>
      <p>研究开始前，我们约定了一条挑选模型版本的规则：从已测的 11 个版本里，寻找最早的一个，使后面所有已测版本的平均分都没有比它高出超过 2 分（满分 100），完整成功的题数也没有多出超过 2 道（共 64 道）。原始英文收据把它称作 practical plateau；这只是“后面的版本没有明显超过它”的判断规则。历史 β/GDR 在第 130 轮后成绩下降，不能被理解成成绩始终平稳。这里的结论只适用于这批事先固定的 64 道题。</p>
      <div class="advisor-viz__table research-booktabs-wrap" tabindex="0">
        <ResearchPaperTable class="research-booktabs" data-q01-measured-table>
          <caption>补充表 S1｜同一冻结 64 题；Task Score（满分 100 分）（仅列出已实际测量的保存点）</caption>
          <thead><tr><th scope="col">轮次或更新数</th><th scope="col" data-numeric>普通 OpenEVO</th><th scope="col" data-numeric>Bounded</th><th scope="col" data-numeric>历史 β/GDR</th></tr></thead>
          <tbody>
            {q01Rounds.map((round) => (
              <tr>
                <th scope="row">{round}</th>
                {q01Series.map((item) => (
                  <td data-numeric>{item.values.find((row) => row.round===round)?.score.toFixed(2)} 分</td>
                ))}
              </tr>
            ))}
          </tbody>
        </ResearchPaperTable>
      </div>
    </details>
  </figure>
)}
{variant === 'q02' && (
  <div class="advisor-viz" data-report-visual="q02-early-sft" data-evidence-shape="measured-paper-table">
    <div class="advisor-viz__table research-booktabs-wrap" tabindex="0">
      <ResearchPaperTable class="research-booktabs">
        <caption>表 1｜早期 SFT 在同一批固定购物题上的成绩</caption>
        <thead><tr><th scope="col">训练条件</th><th scope="col" data-numeric>Task Score（满分 100 分）</th></tr></thead>
        <tbody>{earlySft.map(item => (
          <tr><th scope="row">{item.name}</th><td data-numeric>{item.score.toFixed(2)} 分</td></tr>
        ))}</tbody>
      </ResearchPaperTable>
    </div>
    <p class="advisor-viz__table-note">单条历史 SFT 路线的已测得分。六格重复训练的统一配对科学评测尚未封存；这张表不用于判定 SFT 与 OPSD 的最终胜负。</p>
  </div>
)}
{variant === 'q03' && (
  <div class="advisor-q03-paper" data-q03-report-paper data-report-table="q03-checkpoints" data-advisor-matrix="q03" data-matrix-kind="historic-checkpoints" data-protocol="custom-q17-64">
    <div class="advisor-q03-paper__scroll research-booktabs-wrap" tabindex="0" aria-label="四个 Stage2 保存点的 LaTeX 论文式成绩表">
      <table class="research-booktabs advisor-q03-paper__table" data-q03-paper-table>
        <caption>补充表 S2｜四个 Stage2 保存点成绩</caption>
        <thead><tr>
          <th scope="col">保存点</th>
          <th scope="col" data-numeric>Task Score / 100</th>
          <th scope="col" data-numeric>完整成功 / 64 题</th>
        </tr></thead>
        <tbody>{ADVISOR_Q03_CUSTOM_PANEL.map((point) => (
          <tr data-q03-checkpoint={point.update}>
            <th scope="row">{point.update}</th>
            <td data-numeric>{point.score}</td>
            <td data-numeric>{point.exact.replace(/\s*\/\s*\d+$/, '').trim()}</td>
          </tr>
        ))}</tbody>
      </table>
    </div>
    <p class="advisor-q03-paper__reading">四次实测成绩先升、后降、再回升。每个保存点评测了 64 道题，<strong>均没有完整成功的题目</strong>。没有测量中间轮次，不能当成完整训练曲线。</p>
    <p class="advisor-q03-paper__boundary">这组自定义测试与 SEED 论文的 128 题评测协议不同，不能直接相减排名。<a href="https://github.com/mykcs/openevo-experiment/pull/678" target="_blank" rel="noopener noreferrer"><ExternalBrandMark href="https://github.com/mykcs/openevo-experiment/pull/678" />原始评测记录</a></p>
    <details class="advisor-q03-paper__trend" data-q03-trend-details>
      <summary>展开查看折线图（只连接四个实测点）</summary>
      <figure class="advisor-viz advisor-viz--q03" data-report-figure="q03-custom-curve" data-paper-width="single" data-evidence-shape="paper-static-observations" data-protocol="custom-q17-64">
      <PublicationPlot
        id="q03-stage2"
        src="/research/seed-openevo/figures/q03-stage2-pgfplots.svg"
        captionId="advisor-q03-publication-caption"
        loading="eager"
        alt="自定义 64 道 WebShop 任务中四个已测 Stage2 保存点的 Task Score：A0 为 3.71，A40 为 6.43，A80 为 0.69，A120 为 6.62；满分 100，此图仅展示 0 至 10 的局部纵轴。虚线只连接已测保存点。"
      />
      <figcaption id="advisor-q03-publication-caption"><strong>图 2｜</strong>四个 Stage2 实测保存点的 Task Score（自定义 64 题）。纵轴局部显示 0–10 分，实际满分 100；虚线只连接已测点，<strong>没有测量中间轮次</strong>。不能视为完整训练曲线，亦不同于 SEED 论文的 128 题评测协议。</figcaption>
      </figure>
    </details>
  </div>
)}
{variant === 'q04' && (
  <div class="advisor-viz" data-report-figure="q04-capacity" data-evidence-shape="paired-paper-table">
    <div class="advisor-viz__table research-booktabs-wrap" tabindex="0" aria-label="长期状态容量和 WebShop 得分对照表">
      <ResearchPaperTable class="research-booktabs">
        <caption>表 3｜固定容量与后段任务表现</caption>
        <thead>
          <tr>
            <th scope="col">长期参数状态</th>
            <th scope="col" data-numeric>参数文件（MB）</th>
            <th scope="col" data-numeric>Task Score（满分 100 分）</th>
            <th scope="col" data-numeric>完整成功率</th>
          </tr>
        </thead>
        <tbody>
          {ADVISOR_Q04_CAPACITY.map((item) => (
            <tr>
              <th scope="row">{item.method}</th>
              <td data-numeric>{item.bytes.replace(' MB', '')}</td>
              <td data-numeric>{item.score}</td>
              <td data-numeric>{item.exact}</td>
            </tr>
          ))}
        </tbody>
      </ResearchPaperTable>
    </div>
    <p class="advisor-viz__table-note">两种容量使用第 152–159 轮的 1,024 组同任务、同随机条件配对尝试；参数文件大小测于第 159 轮末。表中的得分和成功率均来自该后段窗口。</p>
  </div>
)}
{variant === 'q05' && (
  <div class="advisor-viz" data-report-figure="q05-same-final" data-evidence-shape="frozen-paper-table">
    <div class="advisor-viz__table research-booktabs-wrap" tabindex="0">
      <ResearchPaperTable class="research-booktabs">
        <caption>补充表 S5｜三条历史路线在固定 128 题上的训练后成绩</caption>
        <thead><tr><th scope="col">历史路线</th><th scope="col" data-numeric>Task Score（满分 100 分）</th><th scope="col" data-numeric>完整成功题数（共 128 题）</th></tr></thead>
        <tbody>{ADVISOR_Q05_FROZEN.map(item => (
          <tr><th scope="row">{item.method.replace(' / DirectApply','')}</th><td data-numeric>{item.score} 分</td><td data-numeric>{item.exact.replace(/\s*\/\s*\d+$/, '').trim()} 题</td></tr>
        ))}</tbody>
      </ResearchPaperTable>
    </div>
    <p class="advisor-viz__table-note">普通 OpenEVO 是较早的历史前序路线。三个终点使用同一冻结题单，但训练起点没有构成完全匹配的随机三臂试验。</p>
  </div>
)}
{variant === 'q07' && (
  <div data-report-visual="q07-confidence-interval" data-evidence-shape="confidence-interval">
    <PaperIntervalPlot id="q07-inversion" title="第 156 轮反转一次 Task Vector 的局部效果" unit="Task Score 成绩变化（分）" min={-20} max={5} ticks={[-20,-10,0,5]} effects={[{id:'inverse',label:'Bounded OFF · 方向反转',estimate:-10.06,low:-15.02,high:-5.60}]} comparison="第 156 轮的更新方向反转后 − 原始 Bounded OFF 模型；相同 64 道购物题" negativeLabel="反转后分数更低" positiveLabel="反转后分数更高" caption="图 6｜Q07 第 156 轮方向反转：同一冻结 64 题的配对 Task Score 变化；95% 置信区间对应下降 5.60 至 15.02 分，没有包含零。这是八次方向反转中通过预设多重比较校正的一次，不能推广成普适的在线方向控制规则。" />
  </div>
)}

---
import ExternalBrandMark from '../common/ExternalBrandMark';
import type { Locale } from '../../i18n';
import OpenEvoEvidenceRefs from './OpenEvoEvidenceRefs.astro';
import type { EvidenceRef } from '../../lib/researchEvidence';

interface Props { locale: Locale }
const { locale } = Astro.props;
const zh = locale === 'zh';
const t = (cn: string, en: string) => zh ? cn : en;

const experimentRoot = 'https://github.com/mykcs/openevo-experiment/blob/115062ea0b47ee769a3e1591ffd3d5c89c4a353a';
