    ],
    boundary: t('问题不在 SEED 的动作读取代码违反了自己的规则，也不是提示词要求模型输出 [action]。实际情况是：模型会偶尔把外层标签写错，而我们在正式评测前没有拿真实模型输出检查“评测器能不能正确读懂”。因此责任在实验集成这一层。更深的代码和运行记录放在下面的实验依据里。', 'The SEED action reader was following its own rule, and the prompt did not ask the model to output [action]. The model could occasionally write the outer label incorrectly, and we failed to test real model outputs through the evaluator before the formal run. The integration layer therefore owns this failure. Deeper code and run records are kept in the evidence below.'),
    links: [
      seedParser,
      seedPrompt,
      { kind: 'raw-episode', label: t('BASE 原始回合', 'BASE raw episode'), href: `${rawBaseEpisode}#L2-L53` },
      { kind: 'code', label: t('Transformers 推理后端', 'Transformers inference backend'), href: `${rawEpisodeRoot}/vendor/openevo-webshop/src/openevo_webshop/inference.py#L227-L232` },
      { kind: 'human-report', label: t('PRIMARY-v1 根因与修复后结果', 'PRIMARY-v1 root cause and repaired result'), href: `${seedHeldoutRoot}/docs/evidence/seed-official-heldout-comparison-v1/RESULTS.md` },
      primaryV2Analysis,
      { kind: 'machine-result', label: t('H1.42 Stage B 对账', 'H1.42 Stage B reconciliation'), href: `${h142Root}/docs/evidence/remote-runs/2026-08-21/h1.42-mv/stage-b-reconciliation.json` },
    ],
  },

];

const transferRows = [
  { label: t('第一次迁移 · SD-LoRA − BASE', 'First transfer · SD-LoRA − BASE'), value: '+0.124', ci: '[0.0326, 0.2194]', left: '20.7%', width: '46.7%', point: '43.5%' },
  { label: t('独立复现 · ordinary-LoRA − BASE', 'Independent replication · ordinary-LoRA − BASE'), value: '+0.164', ci: '[0.0781, 0.2519]', left: '32.0%', width: '43.5%', point: '53.4%' },
  { label: t('独立复现 · SD-LoRA − BASE', 'Independent replication · SD-LoRA − BASE'), value: '+0.249', ci: '[0.1642, 0.3365]', left: '53.6%', width: '43.0%', point: '74.7%' },
] as const;
---

<section class="results-questions" id="questions" aria-labelledby="questions-title">
  <header class="section-heading">
    <div>
      <h2 id="questions-title">{t('七个研究问题', 'Seven research questions')}</h2>
      <p>{t('这七个问题分别检查训练是否真的发生、成功经验能不能写进参数、学到的东西能不能迁移、连续更新能不能保持，以及测量本身是否可靠。最后一个问题回到 OpenEvo 与 SEED 还缺哪一组公平对照。', 'The seven questions cover whether training actually occurred, whether successful experience can be written into parameters, whether learning transfers and survives repeated updates, whether the measurement itself is reliable, and what fair OpenEvo-versus-SEED comparison is still missing.')}</p>
    </div>
  </header>

  <aside class="audit-time" aria-labelledby="audit-time-title">
    <div class="audit-time__intro">
      <h3 id="audit-time-title">{t('动作读取与任务身份', 'Action reading and task identity')}</h3>
      <p>{t('这一段时间主要拆开了两个会把结论带偏的问题：评测程序有没有正确读懂模型动作，以及实际使用的 128 个任务是否真的与 SEED 公开代码生成的任务一致。', 'Most of this time went into separating two issues that could otherwise be mistaken for method differences: whether the evaluator correctly understood the model action, and whether the 128 tasks actually matched what the released SEED code generates.')}</p>
    </div>
    <div class="audit-time__grid">
      <article><strong>{t('① 动作读取', '① Action reading')}</strong><p>{t('SEED 规定动作要放在 <action>...</action> 里面，我们给基础模型的提示也要求这个格式；但模型的原始输出有时会写成 [action]...。第一次正式评测前，我们没有拿真实模型输出检查“评测程序能不能正确读懂”，所以必须先修测量，再讨论模型能力。', 'SEED requires actions inside <action>...</action>, and the prompt sent to the base model asks for the same format; yet raw model output can sometimes use [action].... Before the first formal evaluation, we did not test real model outputs to confirm that the evaluator could read them correctly, so the measurement had to be repaired before interpreting model ability.')}</p></article>
      <article><strong>{t('② 128 个任务的身份', '② Identity of the 128 tasks')}</strong><p>{t('SEED 的公开代码可以重建一批具体的 128 个验证任务，我们已经把这批任务固定成可复查的清单。但论文没有公开 89.7 / 78.1% 当时具体使用的是哪一次验证任务、哪一个模型保存点，因此仍不能把这批题冒充成论文最终 128 题。', 'The released SEED code can rebuild one concrete set of 128 validation tasks, and we have frozen that set into a reviewable list. The paper does not publish which validation run or model checkpoint produced 89.7 / 78.1%, so this panel still cannot be relabelled as the paper-final 128 tasks.')}</p></article>
    </div>
  </aside>

  <div class="question-list">
    {questions.map((item) => (
      <article class:list={['question-card', `tone-${item.tone}`]} id={item.id}>
        <div class="question-number">{item.index}</div>
        <div class="question-copy">
          <div class="question-meta"><span class="status-badge"><i aria-hidden="true"></i>{item.status}</span></div>
          <h3>{item.question}</h3>
          <p class="conclusion">{item.conclusion}</p>
          <p class="supporting-context">{item.boundary}</p>

          {item.id === 'q5' && <p class="forward-ref"><a href="#g2-ablation">{t('查看第二代三道能力门 ↓', 'See the second-generation capability gates ↓')}</a></p>}

          <details class="evidence-details" id={`evidence-${item.id}`} name="research-evidence">
            <summary>{t('展开实验依据', 'Expand experiment evidence')}</summary>
            <div class="evidence-detail-body">
              <table class="obs-table">
                <tbody>
                  {item.observations.map((row) => (
                    <tr>
                      <th scope="row">{row.label}</th>
                      <td>
                        <span>{row.value}</span>
                        <OpenEvoEvidenceRefs locale={locale} sources={row.sources ?? []} compact />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>

              {item.id === 'q4' && (
                <figure class="transfer-figure" data-research-figure-size="wide" data-ui-audit="contrast layout overflow" aria-label={t('H1.38B 与 H1.39 迁移置信区间', 'H1.38B and H1.39 transfer confidence intervals')}>
                  <div class="forest">
                    <div class="forest-scale" aria-hidden="true"><span class="scale-label scale-min">−0.05</span><span class="scale-label scale-zero">0</span><span class="scale-label scale-mid">+0.15</span><span class="scale-label scale-max">+0.35</span><i class="zero-line"></i></div>
                    {transferRows.map((row) => (
                      <div class="forest-row">
                        <div class="forest-label"><strong>{row.label}</strong><span>Δ {row.value} · 95% CI {row.ci}</span></div>
                        <div class="forest-track" aria-hidden="true"><i class="zero-line"></i><span class="ci-line" style={`left:${row.left};width:${row.width}`}></span><b class="point" style={`left:${row.point}`}></b></div>
                      </div>
                    ))}
                  </div>
                  <figcaption>{t('点表示平均差异，横线表示 95% 置信区间（confidence interval）；竖线表示“没有差异”。三条区间都完整位于 0 以上。', 'Points show the average difference; horizontal lines show 95% confidence intervals; the vertical line marks zero difference. All three intervals lie entirely above zero.')}</figcaption>
                </figure>
              )}

              <p class="claim-boundary"><strong>{t('证据层边界：', 'Evidence-layer boundary: ')}</strong>{item.boundary}</p>
              <OpenEvoEvidenceRefs locale={locale} sources={item.links} ariaLabel={t('这一问题的完整证据材料', 'Full evidence package for this question')} />
            </div>
          </details>
        </div>
      </article>
    ))}
  </div>
</section>

